import type { LocaleText } from '../types';

interface AdvancedStepContent {
  derivation: LocaleText[];
  workedExample: LocaleText;
  implementation: { language: string; code: string };
  advancedExercise: LocaleText;
}

const t = (zh: string, en: string): LocaleText => ({ zh, en });

const a = (
  mathZh: string,
  mathEn: string,
  exampleZh: string,
  exampleEn: string,
  code: string,
  exerciseZh: string,
  exerciseEn: string,
): AdvancedStepContent => ({
  derivation: [t(mathZh, mathEn)],
  workedExample: t(exampleZh, exampleEn),
  implementation: { language: 'python', code },
  advancedExercise: t(exerciseZh, exerciseEn),
});

const content: Record<string, AdvancedStepContent[]> = {
  tokenizer: [
    a('UTF-8 将 Unicode 码点编码为 1 到 4 字节。byte-level 表示的可覆盖性是 256 个基础符号，而不是“每种字符一个字节”；规范化若不可逆，则 encode/decode 的恒等式只在规范化后的文本上成立。', 'UTF-8 encodes a Unicode code point into one to four bytes. Byte-level coverage comes from 256 base symbols, not one byte per character; if normalization is lossy, encode/decode identity holds only for normalized text.', '“大”的 UTF-8 是 E5 A4 A7，所以初始序列长度为 3 字节；经过一次学习到的大+模合并后，token 数才可能下降。英文 hello 通常可从 5 个字符合并成 1 个 token。', 'The UTF-8 bytes for the Chinese character da are E5 A4 A7, so its initial sequence has three byte symbols. A learned merge can later reduce token count; hello may merge from five characters into one token.', 'text = "大模型"\nraw = text.encode("utf-8")\nprint(list(raw))\nassert raw.decode("utf-8") == text\nnormalized = text.normalize("NFKC")\nprint(normalized.encode("utf-8"))', '收集 100 个包含全角字符、组合音标、零宽连接符和代码缩进的样本，分别测试 NFC/NFKC。记录哪些转换不可逆，并说明线上应接受哪一种契约。', 'Collect 100 cases with full-width characters, combining accents, zero-width joiners and indentation. Test NFC/NFKC, record irreversible changes and define the production contract.'),
    a('BPE 每次合并把语料中一对符号替换为一个新符号。若一对出现 c 次，理想情况下序列总长度减少 c；真实收益受重叠匹配和合并优先级影响。词表预算 V 决定 merge 数约为 V-V0-Vspecial。', 'A BPE merge replaces a symbol pair with one new symbol. If the pair occurs c times, ideal sequence length falls by c, subject to overlapping matches and merge priority. Vocabulary budget V gives roughly V-V0-Vspecial merges.', '语料 abab 中相邻对 (a,b) 出现 2 次，合并为 Z 后序列 ZZ 从 4 个符号降到 2 个；若随后学习 (Z,Z)->Q，最终为 Q。', 'In abab, pair (a,b) occurs twice. Merging it into Z yields ZZ, reducing four symbols to two; a later merge (Z,Z)->Q yields Q.', 'from collections import Counter\nsymbols = list("abab")\npairs = Counter(zip(symbols, symbols[1:]))\nbest = max(pairs, key=pairs.get)\nprint(best, pairs[best])\nmerged = ["Z" if a == "a" and b == "b" else a for a, b in zip(symbols, symbols[1:])]\nprint(merged)', '不要用上面的简化合并代码直接训练大词表。实现一个优先队列版本，比较每次全量重数与增量更新在 1GB 语料上的时间和内存。', 'Do not use the simplified merge code for large-vocabulary training. Implement a priority-queue version and compare full recounts with incremental updates on a 1GB corpus.'),
    a('嵌入查表是 one-hot 矩阵乘的优化：x_one_hot E 等价于直接选择 E[x]。参数量为 Vd；输入与输出不共享时总词表参数为 2Vd，共享后为 Vd，但输出 logit 的缩放和初始化分布也会改变。', 'Embedding lookup optimizes one-hot matrix multiplication: x_one_hot E equals selecting E[x]. Parameters are Vd; separate input/output vocab matrices cost 2Vd while tying costs Vd, but output-logit scaling and initialization also change.', 'V=32000、d=4096 时单份嵌入有 131,072,000 个参数，BF16 约 250MiB。若模型本身只有 1B 参数，这份词表矩阵已占约 13.1%。', 'With V=32000 and d=4096, one embedding matrix has 131,072,000 parameters, about 250MiB in BF16. For a 1B-parameter model, this matrix alone is about 13.1%.', 'import torch\nvocab, d = 32000, 4096\nembedding = torch.nn.Embedding(vocab, d)\nids = torch.tensor([[3819, 772]])\nh = embedding(ids)\nassert h.shape == (1, 2, d)\nlogits = h @ embedding.weight.T\nassert logits.shape == (1, 2, vocab)', '比较 tied/untied 在参数量、梯度更新和输出 logit 范围上的差异。特别检查新增 token 后 optimizer 是否为新增行建立了状态。', 'Compare tied and untied embeddings for parameter count, gradient updates and logit range. After adding tokens, verify that the optimizer initializes state for the new rows.'),
    a('缓存键必须满足同文本同模型语义推出同 token 前缀。可写为 key=H(model,tokenizer,template,adapters,prefix_ids)。Attention 配对约随 T² 增长，而 KV 容量随 T 线性增长，两者不能混为一项。', 'A cache key must map identical model semantics to identical token prefixes: key=H(model,tokenizer,template,adapters,prefix_ids). Attention pairs grow roughly with T squared while KV capacity grows linearly with T.', '同一 1000 字中文文档在 tokenizer A 下为 900 token，在 B 下为 1300 token。8K 窗口并不能直接比较“字数”，训练样本打包效率也会改变。', 'A 1000-character Chinese document may produce 900 tokens with tokenizer A and 1300 with B. An 8K window cannot be compared by character count, and sample-packing efficiency changes too.', 'import hashlib, json\ndef cache_key(model, tokenizer_hash, template_hash, ids):\n    payload = json.dumps([model, tokenizer_hash, template_hash, ids], separators=(",", ":"))\n    return hashlib.sha256(payload.encode()).hexdigest()\nkey = cache_key("qwen", "tok-v3", "chat-v2", [101, 3819, 772])\nprint(key)', '构造 tokenizer 升级但模型未变、模板变化但文本不变、LoRA 切换三组案例，验证缓存不会错误命中，并统计误命中的代价。', 'Construct cases for a tokenizer upgrade, template-only change and adapter switch. Verify invalid cache entries miss and estimate the cost of a false hit.'),
  ],
  attention: [
    a('one-hot 向量 e_id 乘 E[V,d] 的结果是 E 的第 id 行，因此查表与矩阵乘数学等价但计算量不同。加入 P[T,d] 后 H0[b,t,c]=E[id[b,t],c]+P[t,c]， batch 维只广播位置，不混和样本。', 'A one-hot vector e_id times E[V,d] selects row id, making lookup mathematically equivalent but computationally cheaper than dense matmul. With P[T,d], H0[b,t,c]=E[id[b,t],c]+P[t,c]; batch broadcasts positions without mixing samples.', '动画中 id 序列 [42,517,1803,91] 产生 X[4,4]。例如 H0[0,0]=0.20+0.00=0.20，H0[3,0]=0.50+0.20=0.70；每个元素都能回查到具体嵌入行和位置。', 'The scene maps IDs [42,517,1803,91] to X[4,4]. For example H0[0,0]=0.20+0.00=0.20 and H0[3,0]=0.50+0.20=0.70; every value traces to an embedding row and position.', 'import torch\nids = torch.tensor([42,517,1803,91])\nE = torch.randn(2048,4)\nP = torch.randn(4,4)\nX = E[ids]\nH0 = X + P\nassert X.shape == H0.shape == (4,4)\nassert torch.equal(H0, E[ids] + P)\nprint(H0)', '把位置嵌入换成正弦编码，保持 X 不变，比较 H0 的数值与后续 Logits。再实现 padding 位置是否加入 P 的两种策略并解释语义。', 'Replace learned positions with sinusoidal encodings while keeping X fixed; compare H0 and downstream logits. Then compare including versus excluding positions at padding tokens.'),
    a('RMSNorm(x)=x/sqrt(mean(x^2)+eps) 逐 Token 缩放。RoPE 对每对通道做 [[cos,-sin],[sin,cos]] 旋转，正交矩阵保持二维范数；不同位置使用不同角度，使 QK 点积感知相对位移。', 'RMSNorm(x)=x/sqrt(mean(x^2)+eps) scales each token. RoPE applies [[cos,-sin],[sin,cos]] to channel pairs; orthogonal rotation preserves 2D norms while position-dependent angles make QK products relative-position aware.', '对二维向量 [a,b]，旋转后的范数平方为 (a cos-b sin)^2+(a sin+b cos)^2=a^2+b^2。动画中位置 0 的旋转角为 0，因此 t0 的 Q/K 不变，后续位置才旋转。', 'For [a,b], squared norm after rotation is (a cos-b sin)^2+(a sin+b cos)^2=a^2+b^2. In the scene position zero has angle zero, so t0 Q/K stay unchanged while later positions rotate.', 'import torch\ndef rms_norm(x,eps=1e-6):\n    return x * torch.rsqrt(x.square().mean(-1,keepdim=True)+eps)\ndef rope(x,pos,base=10000):\n    pair = x.reshape(*x.shape[:-1],-1,2)\n    angle = pos / (base ** torch.arange(pair.shape[-2],device=x.device)/pair.shape[-2])\n    c,s = angle.cos()[...,None],angle.sin()[...,None]\n    a,b = pair[...,0:1],pair[...,1:2]\n    return torch.cat([a*c-b*s,a*s+b*c],-1).flatten(-2)\nx = torch.randn(4,4)\nassert torch.allclose(rope(x,0),x)\nprint(rms_norm(x))', '推导两个位置 m,n 经 RoPE 后点积只依赖 m-n 的条件。把 base 从 10000 改为 500000，比较不同通道对的旋转速度和长上下文外推。', 'Derive when RoPE dot products at positions m,n depend only on m-n. Change base from 10000 to 500000 and compare pair frequencies and long-context extrapolation.'),
    a('若 Q,K 各分量独立、均值 0、方差 1，则 Var(q dot k) 约为 d_head，所以除以 sqrt(d_head) 控制尺度。稳定 Softmax 利用 softmax(x)=softmax(x-c)，选 c=max(x) 防止 exp 上溢；mask 必须在归一化前加入。', 'For independent zero-mean unit-variance Q/K components, Var(q dot k) is about d_head, motivating division by sqrt(d_head). Stable softmax uses softmax(x)=softmax(x-c) with c=max(x) to avoid overflow; masks apply before normalization.', '动画头 0 的第 0 行只有 S[0,0] 可见，因此 A[0,0]=1。第 3 行可使用全部 4 个 Key，而第 1 行只能使用前 2 个；每行概率和都为 1，上三角全部为 0。', 'In scene head zero, row zero sees only S[0,0], hence A[0,0]=1. Row three uses all four keys while row one uses two; every row sums to one and the upper triangle is zero.', 'import torch\ndef causal_attention_weights(q,k):\n    scores = q @ k.transpose(-1,-2) / q.shape[-1]**0.5\n    t = q.shape[-2]\n    mask = torch.triu(torch.ones(t,t,dtype=torch.bool),1)\n    scores = scores.masked_fill(mask,float("-inf"))\n    weights = torch.softmax(scores.float(),-1)\n    assert torch.allclose(weights.sum(-1),torch.ones(t),atol=1e-6)\n    return weights\nq,k = torch.randn(4,2),torch.randn(4,2)\nprint(causal_attention_weights(q,k))', '对比直接 exp 与减最大值版本在 scores=[1000,1001] 上的结果；再构造全 mask 行，明确应报错、返回零还是跳过该位置。', 'Compare naive exponentials with max subtraction at scores=[1000,1001]. Then construct a fully masked row and define whether to raise, return zero or skip it.'),
    a('C_h[i,:]=sum_j A_h[i,j]V_h[j,:] 是矩阵乘的行展开。拼接只重排通道，Wo 再执行线性混合。残差 H1=H0+C Wo 的雅可比含单位矩阵，为梯度提供直接通路，但不保证任何深层网络都必然稳定。', 'C_h[i,:]=sum_j A_h[i,j]V_h[j,:] expands one matmul row. Concatenation reorders channels and Wo mixes them linearly. Residual H1=H0+C Wo includes an identity Jacobian path, though it does not guarantee stability for every deep network.', '若某头第 2 行权重为 [a,b,c,0]，则输出只含 V0,V1,V2，且系数和为 1。动画分别计算两个 [4,2] 上下文，再拼为 C[4,4]；H1-H0 必须逐元素等于 C Wo。', 'If head row two has weights [a,b,c,0], its output uses only V0,V1,V2 with coefficients summing to one. The scene computes two [4,2] contexts, concatenates C[4,4], and requires H1-H0=C Wo elementwise.', 'import torch\ndef attention_block(h0,wq,wk,wv,wo):\n    q,k,v = h0@wq,h0@wk,h0@wv\n    scores = q@k.transpose(-1,-2)/q.shape[-1]**0.5\n    mask = torch.triu(torch.ones(q.shape[1],q.shape[1],dtype=torch.bool),1)\n    a = (scores.masked_fill(mask,float("-inf"))).softmax(-1)\n    context = a@v\n    return h0 + context@wo\nh0 = torch.randn(4,4)\nw = [torch.randn(4,4) for _ in range(4)]\nh1 = attention_block(h0,*w)\nassert h1.shape == h0.shape', '把单头代码改成两个头，并与 PyTorch scaled_dot_product_attention 对照。随后求 H1 对 H0 的雅可比范数，观察残差通路和 Attention 分支的贡献。', 'Extend the single-head code to two heads and compare with PyTorch scaled_dot_product_attention. Then inspect the Jacobian norm from H1 to H0 for residual and attention paths.'),
    a('GELU(x)=x Phi(x)，常用 tanh 近似为 0.5x[1+tanh(sqrt(2/pi)(x+0.044715x^3))]。FFN 对 [B,T,d] 最后两维做矩阵乘，B,T 都是独立行；残差以 H1 为基底而不是回到 H0。', 'GELU(x)=x Phi(x), commonly approximated by 0.5x[1+tanh(sqrt(2/pi)(x+0.044715x^3))]. FFN matmuls act on the final axes of [B,T,d], treating B,T as independent rows; the residual base is H1, not H0.', '动画采用 d_ff=2d=8，所以 RMSNorm(H1)[4,4] 乘 W1[4,8] 得 U[4,8]，再乘 W2[8,4] 回到 [4,4]。GELU 不改变形状，但会逐元素改变正负与幅值。', 'The scene uses d_ff=2d=8: RMSNorm(H1)[4,4] times W1[4,8] gives U[4,8], then W2[8,4] returns [4,4]. GELU preserves shape but changes signs and magnitudes elementwise.', 'import torch\nclass FFN(torch.nn.Module):\n    def __init__(self,d=4,hidden=8):\n        super().__init__()\n        self.w1 = torch.nn.Linear(d,hidden,bias=False)\n        self.w2 = torch.nn.Linear(hidden,d,bias=False)\n    def forward(self,x):\n        return self.w2(torch.nn.functional.gelu(self.w1(x)))\nh1 = torch.randn(4,4)\nffn = FFN()\nu = ffn.w1(h1)\nassert u.shape == (4,8)\nh2 = h1 + ffn(h1)\nassert h2.shape == h1.shape', '把 GELU 换成 ReLU 和恒等映射，比较 U 的零值比例、H2 范数和反向梯度。再扫描 d_ff/d，记录参数量和实际吞吐变化。', 'Replace GELU with ReLU and identity; compare zero fraction, H2 norms and gradients. Sweep d_ff/d while recording parameter count and measured throughput.'),
    a('词表投影对最后隐藏态 z 计算 z Wout^T。Softmax 后 p_c=exp(z_c)/sum_v exp(z_v)，目标 y 的 CE=-log p_y=-z_y+logsumexp(z)。训练时位置 t 的 Logits 对应目标 t+1，padding 和 prompt 是否监督由 mask 决定。', 'Vocabulary projection computes z Wout^T. After softmax p_c=exp(z_c)/sum_v exp(z_v), target y has CE=-log p_y=-z_y+logsumexp(z). During training logits at t predict target t+1; masks decide whether padding and prompt are supervised.', '动画只展开最后位置的 6 个 Logits，并选择目标 !。页面直接计算 CE=-log p[!]；如果把 Softmax 概率再传给 F.cross_entropy，会重复取 Log，得到不同损失。', 'The scene expands six logits at the last position with target !. It computes CE=-log p[!]; passing softmax probabilities into F.cross_entropy would take another logarithm and produce a different loss.', 'import torch\nlogits = torch.tensor([[0.2,-0.1,0.4,0.3,0.7,0.5]])\ntarget = torch.tensor([5])\np = logits.softmax(-1)\nmanual = -p[0,target].log()\nframework = torch.nn.functional.cross_entropy(logits,target)\nassert torch.allclose(manual,framework)\nprint(manual.item())', '把单 Block 扩展为 L 层，每层独立参数，验证 H 形状不变。再构造完整输入 [I,like,large,models] 与右移标签，逐位置列出预测目标和 mask。', 'Extend one block to L layers with independent parameters and verify hidden shape stays fixed. Build full inputs [I,like,large,models] with shifted targets and list each prediction target and mask.'),
  ],
  backprop: [
    a('计算图节点保存的是构造向量雅可比积所需闭包。Y=XW 的前向需保存 X 和 W 才能分别算 dW=X^TG、dX=GW^T。激活显存因此与算子实现有关，而不是“所有中间输出都保存”。', 'A graph node saves the closure needed for its vector-Jacobian product. For Y=XW, X and W are needed for dW=X^TG and dX=GW^T. Activation memory is operator-specific; not every intermediate output is saved.', 'X=[B,T,in]、W=[in,out] 时，保存 X 的元素数是 B*T*in；若 T 翻倍，反向所需激活近似翻倍，但 W 大小不变。', 'For X [B,T,in] and W [in,out], saved X contains B*T*in elements. Doubling T roughly doubles this backward activation while W remains unchanged.', 'import torch\nx = torch.randn(2,3,4,requires_grad=True)\nw = torch.randn(4,5,requires_grad=True)\ny = x @ w\nprint(y.grad_fn)\nprint(y.grad_fn.next_functions)\ny.sum().backward()\nassert x.grad.shape == x.shape\nassert w.grad.shape == w.shape', '分别测试 detach、no_grad、inplace 和 retain_graph。记录哪些产生错误、哪些静默改变梯度，并解释版本计数器检测到的是什么。', 'Test detach, no_grad, inplace operations and retain_graph. Record errors versus silent gradient changes and explain what version counters detect.'),
    a('链式法则对张量采用内积缩并：若 Y=XW、G=dL/dY，则 dL=<G,dY>=<G,dX W+dW...>，由迹恒等式可得 dX=GW^T、dW=X^TG。形状检查能快速排除大量错误转置。', 'The tensor chain rule uses inner-product contractions. For Y=XW and G=dL/dY, dL=<G,dY>; trace identities give dX=GW^T and dW=X^TG. Shape checks catch many transpose errors.', 'X 为 [2,3]、W 为 [3,4]、G 为 [2,4]，则 G W^T=[2,3]，X^TG=[3,4]。若得到 [2,4] 的参数梯度，即使部分元素相近也应判定错误。', 'For X [2,3], W [3,4] and G [2,4], G W^T is [2,3] and X^TG is [3,4]. A [2,4] parameter gradient is invalid even if some entries look plausible.', 'import torch\ndef linear_backward(x,w,g):\n    dx = g @ w.T\n    dw = x.T @ g\n    assert dx.shape == x.shape\n    assert dw.shape == w.shape\n    return dx,dw\nx,w,g = torch.randn(2,3),torch.randn(3,4),torch.randn(2,4)\ndx,dw = linear_backward(x,w,g)', '手写 LayerNorm backward，分别推 gamma、beta、x 的梯度。先在小矩阵上验证均值与方差依赖，再比较 fused kernel。', 'Hand-derive LayerNorm backward for gamma, beta and x. Validate mean and variance dependencies on small matrices before comparing a fused kernel.'),
    a('中心差分误差为 O(eps²)，单边差分为 O(eps)。但 eps 太小时 f(x+eps)-f(x-eps) 发生灾难性抵消，实际最优 eps 受函数尺度和 dtype 影响。随机方向导数 D_v f=lim(f(x+epsv)-f(x-epsv))/(2eps) 可检查高维函数。', 'Central differences have O(eps squared) truncation error, one-sided differences O(eps). Tiny epsilon causes catastrophic cancellation; optimum depends on function scale and dtype. Random directional derivatives test high-dimensional functions cheaply.', 'f(x)=x³、x=2 时解析导数 12。eps=1e-3 的中心差分为 (2.001³-1.999³)/0.002，约 12.000001；eps 继续降到浮点噪声区后误差反而上升。', 'For f(x)=x cubed at x=2, the analytic derivative is 12. Central difference with eps=1e-3 is about 12.000001; much smaller epsilon eventually increases floating-point error.', 'import torch\ndef f(x): return (x ** 3).sum()\nx = torch.tensor([2.0],dtype=torch.float64,requires_grad=True)\nf(x).backward()\nanalytic = x.grad.detach().clone()\nfor eps in [1e-1,1e-3,1e-5,1e-8]:\n    numeric = (f(x.detach()+eps)-f(x.detach()-eps))/(2*eps)\n    print(eps,float(numeric),float(abs(numeric-analytic)))', '对包含 matmul、Softmax 和 LayerNorm 的复合函数做 eps 扫描，画出截断误差与舍入误差主导的 U 形曲线。', 'Sweep epsilon for a compound function with matmul, softmax and LayerNorm; plot the U-shaped curve from truncation and rounding errors.'),
    a('全局范数 ||g||2=sqrt(sum_i g_i²)，裁剪 g<-g*min(1,tau/||g||)。它只改变异常步更新尺度，不修复前向 NaN。update/param ratio 约为 ||theta_new-theta_old||/||theta_old||，可帮助识别“梯度正常但更新异常”。', 'Global norm is sqrt(sum_i g_i squared), and clipping applies g<-g*min(1,tau/||g||). It limits abnormal-step updates but does not repair forward NaNs. Update-to-parameter ratio compares parameter change with parameter norm.', '若梯度范数为 20、阈值 5，则所有梯度统一乘 0.25，方向不变。若只有某个层为 Inf，总范数也变为 Inf，必须先定位而不是裁剪。', 'With gradient norm 20 and threshold 5, every gradient is multiplied by 0.25 without changing direction. If one layer is Inf, the global norm is Inf; localize it instead of clipping.', 'import torch\nparams = [torch.nn.Parameter(torch.randn(4,4)) for _ in range(3)]\nfor i,p in enumerate(params): p.grad = torch.full_like(p,float(i+1))\nbefore = torch.nn.utils.clip_grad_norm_(params,1.0)\nafter = torch.linalg.vector_norm(torch.stack([p.grad.norm() for p in params]))\nprint(float(before),float(after))\nassert after <= 1.0 + 1e-6', '构造前向 NaN、单层爆炸、极小学习率三种故障，比较 loss、grad norm、param norm 和 update ratio 的可见顺序。', 'Inject forward NaN, one-layer explosion and tiny LR. Compare the order in which loss, gradient norm, parameter norm and update ratio reveal each fault.'),
  ],
  optimizer: [
    a('Momentum v_t=mu v_(t-1)+g_t 是指数滑动平均。稳态下历史梯度权重为 mu^k，等效时间尺度约 1/(1-mu)。它增加一份与参数同形的 buffer，恢复训练时必须同步恢复。', 'Momentum v_t=mu v_(t-1)+g_t is exponential averaging. Historical gradients have weights mu^k and an effective timescale near 1/(1-mu). It adds one parameter-sized buffer that must be restored on resume.', 'mu=0.9 时，10 步前梯度权重约 0.35，20 步前约 0.12；mu=0.99 时同样 20 步前仍约 0.82，平滑时间明显更长。', 'With mu=0.9, gradients ten steps old have weight about 0.35 and twenty steps old about 0.12. With mu=0.99, twenty-step-old gradients still have weight about 0.82.', 'def momentum(grads,mu=0.9):\n    v = 0.0\n    out = []\n    for g in grads:\n        v = mu*v+g\n        out.append(v)\n    return out\nprint(momentum([1,1,1,0,0,0]))\nprint(momentum([1,-1,1,-1,1,-1]))', '在同一二次函数上扫描 mu 与 lr，找出动量导致振荡的区域。解释为什么不能只按“更快下降”选择超参。', 'Sweep mu and LR on one quadratic objective and locate oscillatory regimes. Explain why fastest initial descent is not a sufficient hyperparameter criterion.'),
    a('Adam m_t=beta1m_(t-1)+(1-beta1)g_t，v_t=beta2v_(t-1)+(1-beta2)g_t²。零初始化使 E[m_t] 含 (1-beta1^t) 因子，因此 m_hat=m/(1-beta1^t)，v 同理。', 'Adam uses m_t=beta1m_(t-1)+(1-beta1)g_t and v_t=beta2v_(t-1)+(1-beta2)g_t squared. Zero initialization introduces factors 1-beta1^t and 1-beta2^t, requiring bias-corrected m_hat and v_hat.', 'beta1=0.9、第一步 g=1 时 m_1=0.1，但偏差修正 m_hat=0.1/(1-0.9)=1。若不修正，第一步方向被人为缩小到 0.1。', 'With beta1=0.9 and first gradient one, m_1=0.1 while corrected m_hat=0.1/(1-0.9)=1. Without correction, the first direction is artificially shrunk to 0.1.', 'g,b1,b2,t = 1.0,0.9,0.999,1\nm = (1-b1)*g\nv = (1-b2)*g*g\nm_hat = m/(1-b1**t)\nv_hat = v/(1-b2**t)\nupdate = m_hat/(v_hat**0.5+1e-8)\nprint(m,v,m_hat,v_hat,update)', '实现前 20 步并比较有无偏差修正的更新轨迹。进一步验证恢复 checkpoint 后 t 错位一步会产生什么偏差。', 'Implement twenty steps with and without bias correction. Then shift restored step t by one and measure the resulting update bias.'),
    a('AdamW 更新 theta=theta-lr*adaptive(g)-lr*wd*theta，衰减项不进入 m/v。若把 wd 加进 loss，则梯度变为 g+wd theta，并会被二阶矩和自适应分母缩放，语义不同。', 'AdamW computes theta=theta-lr*adaptive(g)-lr*wd*theta; decay never enters m/v. Adding weight decay to the loss changes gradients to g+wd theta and lets adaptive normalization rescale decay, which is different.', 'g=0、lr=0.01、wd=0.1、theta=2 时，AdamW 仍有衰减更新 -0.002；若纯 Adam 且无 L2 梯度，参数不变。', 'With g=0, lr=0.01, wd=0.1 and theta=2, AdamW still applies -0.002 decay. Plain Adam without L2 gradient leaves the parameter unchanged.', 'import torch\np = torch.nn.Parameter(torch.tensor([2.0]))\nopt = torch.optim.AdamW([p],lr=0.01,weight_decay=0.1)\np.grad = torch.zeros_like(p)\nopt.step()\nprint(p.item())\nassert p.item() < 2.0', '打印真实框架参数组，验证 norm/bias 是否 no-decay。构造一个包含 norm 字样的普通层，检查字符串匹配是否误分组。', 'Inspect framework parameter groups and verify norm/bias no-decay rules. Add an unrelated layer containing norm in its name to test name-based grouping.'),
    a('Cosine lr_t=lr_min+(lr_max-lr_min)(1+cos(pi t/T))/2。有效步数应按 optimizer update 而非 dataloader microbatch 计算；梯度累积 a 会使调度步数相差 a 倍。', 'Cosine LR is lr_min+(lr_max-lr_min)(1+cos(pi t/T))/2. Scheduler steps should follow optimizer updates, not dataloader microbatches; accumulation by a changes schedule length by a.', '总更新 1000、warmup=100 时，若每 4 微步更新一次，dataloader 总步数是 4000。把 scheduler 每微步调用会让 cosine 在四分之一训练时提前结束。', 'For 1000 updates and warmup 100 with four microsteps per update, the loader has 4000 steps. Calling the scheduler per microstep finishes cosine after one quarter of training.', 'import math\ndef cosine(t,total,peak=3e-4,minimum=3e-5):\n    return minimum+(peak-minimum)*(1+math.cos(math.pi*t/total))/2\nfor t in [0,250,500,750,1000]:\n    print(t,cosine(t,1000))', '做一次短 LR range test，同时记录 grad norm。选择“快速下降且未进入尖峰”的 lr，并说明为何不能选 loss 最低点。', 'Run a short LR range test with gradient norms. Select rapid stable descent before spikes and explain why the minimum-loss LR is often unsafe.'),
  ],
  distributed: [
    a('Ring AllReduce 分 reduce-scatter 与 allgather 两轮，每 rank 发送约 2N(p-1)/p 个元素。全局梯度均值是 1/p sum_r g_r；若各 rank 样本数不同，简单平均不再等于全局样本均值。', 'Ring AllReduce has reduce-scatter and allgather phases, sending about 2N(p-1)/p elements per rank. Global gradient mean is 1/p sum_r g_r; unequal local sample counts make this differ from the global sample mean.', 'N=1GB、p=8 时，理想 ring 每 rank 约 1.75GB 通信，而非 8GB。若有效带宽 40GB/s，仅通信下界约 43.75ms。', 'For N=1GB and p=8, ideal ring traffic is about 1.75GB per rank, not 8GB. At 40GB/s effective bandwidth, the communication-only bound is about 43.75ms.', 'def ring_gb(size_gb,p):\n    return 2*size_gb*(p-1)/p\nfor p in [2,4,8,16]:\n    traffic = ring_gb(1.0,p)\n    print(p,traffic,traffic/40*1000)', '构造两个 rank 样本数不同的 batch，比较简单梯度平均与按样本数加权平均。说明 DDP 默认语义以及如何处理尾批次。', 'Create unequal local batches and compare simple gradient averaging with sample-count weighting. Explain DDP semantics and tail-batch handling.'),
    a('FSDP 在层前 AllGather 参数、层后释放，反向 ReduceScatter 梯度。持久状态约按 DP 数分片，但峰值还包括当前计算单元完整参数、预取层、bucket 和激活。', 'FSDP AllGathers parameters before a unit, releases them afterward and ReduceScatters gradients. Persistent state is DP-sharded, but peak memory includes full current-unit parameters, prefetch, buckets and activations.', '16N bytes 总持久状态、DP=8 时理想每 rank 2N bytes；若当前层完整参数为 2GB、预取另一层 2GB，峰值会额外增加约 4GB，不包含激活。', 'With 16N bytes persistent state and DP=8, ideal persistent memory per rank is 2N bytes. A 2GB current layer plus 2GB prefetch adds about 4GB before activations.', 'def fsdp_peak_gib(total_state_gib,dp,full_layer_gib,prefetch=1,other_gib=0):\n    return total_state_gib/dp+(1+prefetch)*full_layer_gib+other_gib\nprint(fsdp_peak_gib(128,8,2,prefetch=1,other_gib=6))', '比较两种 wrap 粒度，记录 AllGather 次数、峰值和通信暴露。解释为什么 wrap 越细并不总是显存越低。', 'Compare two wrapping granularities for AllGather count, peak and exposed communication. Explain why finer wrapping does not always reduce peak memory.'),
    a('TP 对矩阵分片引入层内集合通信；PP 将层分段，朴素 1F1B 空泡比例约 (p-1)/(m+p-1)，m 为 microbatch 数。增大 m 减空泡但增加调度与部分激活驻留。', 'TP shards matrices and introduces intra-layer collectives; PP shards layers. A simple 1F1B bubble fraction is about (p-1)/(m+p-1) for m microbatches. More microbatches reduce bubbles but add scheduling and activation residency.', 'p=4、m=4 时估算空泡 3/7=42.9%；m=16 时降为 3/19=15.8%。收益递减，因此还需看 microbatch 变小后的 kernel 效率。', 'For p=4 and m=4, estimated bubble fraction is 3/7=42.9%; with m=16 it is 3/19=15.8%. Gains diminish and smaller-microbatch kernel efficiency matters.', 'def bubble(p,m):\n    return (p-1)/(m+p-1)\nfor m in [1,2,4,8,16,32]:\n    print(m,bubble(4,m))', '固定全局 batch，扫描 microbatch，绘制空泡下降与实测吞吐曲线。标出收益被 kernel 效率和显存限制抵消的拐点。', 'With global batch fixed, sweep microbatches and plot theoretical bubbles versus measured throughput. Mark where kernel efficiency and memory cancel the gains.'),
    a('重叠只能隐藏 max(0,Tcomm-Tcompute_after_bucket) 中的部分通信。理想步时间可近似 max(Tcompute,Tcomm)+不可重叠项，而不是 compute+comm 简单相加或完全取零。', 'Overlap hides only communication covered by independent compute. Ideal step time is roughly max(Tcompute,Tcomm) plus exposed terms, neither always a sum nor free communication.', 'bucket 就绪后剩余反向计算 30ms、通信 50ms，则至少约 20ms 通信暴露；若 bucket 提前到剩余计算 50ms，则理论可完全隐藏。', 'If remaining backward compute is 30ms and communication 50ms, at least about 20ms is exposed. Moving the bucket earlier with 50ms independent compute could hide it theoretically.', 'def exposed(compute_after,communication):\n    return max(0,communication-compute_after)\nfor compute in [10,30,50,70]:\n    print(compute,exposed(compute,50))', '用 profiler 对一个 bucket 做时间线归因，区分通信执行、等待依赖、主机提交和慢 rank。给出一种可验证的 bucket 重排实验。', 'Profile one bucket timeline and separate communication execution, dependency waits, host submission and stragglers. Propose a verifiable bucket-reordering experiment.'),
  ],
  memory: [
    a('16 bytes/param=BF16 weight2+BF16 grad2+FP32 master4+Adam m4+Adam v4。它不是通用常数：无 master、8bit optimizer、梯度分片或纯推理都要重写账本。', 'Sixteen bytes per parameter equals BF16 weight 2, BF16 gradient 2, FP32 master 4 and FP32 Adam m/v 4 each. It is not universal: no master weights, 8-bit optimizers, sharded gradients or inference require a new ledger.', '8B 参数按 16 bytes 为 128GB 十进制，约 119.2GiB。若只报告“8B BF16 权重 16GB”，会漏掉训练所需的另外约 112GB。', 'Eight billion parameters at 16 bytes total 128GB decimal, about 119.2GiB. Reporting only 16GB BF16 weights omits roughly another 112GB of training state.', 'def adamw_gib(params_billions,shards=1):\n    return params_billions*1e9*16/shards/1024**3\nprint(adamw_gib(8))\nprint(adamw_gib(8,shards=8))', '分别写出 BF16 AdamW、FP32 Adam、8bit Adam 和纯 BF16 推理的每参数字节数，并标注每项是否分片。', 'Write per-parameter bytes for BF16 AdamW, FP32 Adam, 8-bit Adam and BF16 inference, marking which terms are sharded.'),
    a('BF16 有 8 位指数、7 位尾数，FP16 有 5 位指数、10 位尾数。因此 BF16 范围接近 FP32 而精度较低；FP16 精度更高但易上溢。矩阵乘输入精度与 accumulator 精度可分别配置。', 'BF16 has 8 exponent and 7 mantissa bits; FP16 has 5 exponent and 10 mantissa bits. BF16 has FP32-like range with lower precision; FP16 has more precision but overflows easily. Matmul input and accumulator precision are independent.', 'FP16 最大有限值约 65504，60000*2 会溢出；BF16 能表示该结果但有效精度只有约 8 位十进制有效数字中的 2 到 3 位。', 'FP16 maximum finite value is about 65504, so 60000*2 overflows. BF16 represents that result but provides roughly two to three decimal significant digits.', 'import torch\nx = torch.tensor([60000.0],dtype=torch.float16)\nprint(x*2)\ny = torch.tensor([60000.0],dtype=torch.bfloat16)\nprint(y*2)\na = torch.randn(128,128,dtype=torch.bfloat16)\nout = torch.matmul(a,a)\nprint(out.dtype)', '对 softmax 和 LayerNorm 分别测试输入尺度 1、100、1e4，比较 BF16/FP16 的极值、均值和方差误差，确定哪些操作应保留 FP32。', 'Test softmax and LayerNorm at scales 1, 100 and 10000 in BF16/FP16. Compare extrema, mean and variance errors to decide which operations need FP32.'),
    a('若 checkpoint 段有 k 个算子，前向只保存边界输入，反向额外执行 k 个算子的前向。设原前向成本 F，理想额外成本约该段 F；总训练矩阵工作可由约 4ND 增至接近 5ND 的某些粗算口径，但 Attention 与实现会改变实际值。', 'For a checkpointed segment of k operators, forward stores boundaries and backward reruns k forward operators. If that segment forward cost is F, ideal extra cost is about F. Some rough linear-layer accounting rises toward 5ND from 4ND, but attention and implementation change actual cost.', '某段前向 8ms、保存激活 2GB，重算可省约 2GB 驻留但每步至少增加约 8ms 计算；如果步时间从 40ms 到 48ms，吞吐粗降 16.7%。', 'If a segment forward takes 8ms and stores 2GB activations, recomputation saves about 2GB residency but adds at least about 8ms. A 40ms step becoming 48ms reduces throughput by about 16.7%.', 'import torch\nfrom torch.utils.checkpoint import checkpoint\nlayer = torch.nn.Sequential(torch.nn.Linear(128,128),torch.nn.GELU(),torch.nn.Linear(128,128))\nx = torch.randn(4,128,requires_grad=True)\ny = checkpoint(layer,x,use_reentrant=False)\ny.sum().backward()\nprint(x.grad.norm())', '测三种重算范围，并检查 dropout 输出是否一致。记录“显存节省/新增毫秒”比值，而不是只记录是否 OOM。', 'Measure three recomputation scopes and verify dropout consistency. Report memory saved per added millisecond, not only whether OOM disappears.'),
    a('Offload 暴露时间近似 max(0,Ttransfer-Toverlap)，Ttransfer≈V/R_eff+alpha。Pinned memory 提升 DMA 效率，但页面锁定内存不可过度分配；prefetch 过早又提高 GPU 峰值。', 'Exposed offload time is about max(0,Ttransfer-Toverlap), with Ttransfer about V/R_eff+alpha. Pinned memory improves DMA but is finite; early prefetch raises GPU peak memory.', '8GB 状态经有效 20GB/s 链路传输下界约 0.4s；若可用独立计算只有 0.15s，则至少约 0.25s 暴露，远非“免费 offload”。', 'Transferring 8GB over an effective 20GB/s link has a 0.4s bound. With only 0.15s independent compute, at least about 0.25s remains exposed.', 'def exposed_transfer_gib(volume_gib,bandwidth_gbs,covered_seconds):\n    transfer = volume_gib/bandwidth_gbs\n    return transfer,max(0,transfer-covered_seconds)\nprint(exposed_transfer_gib(8,20,0.15))', '抓一次 D2H/H2D 时间线，区分带宽、页锁定分配、同步和预取依赖。比较 prefetch 提前量对峰值与步时间的双影响。', 'Capture D2H/H2D timelines and separate bandwidth, pinned allocation, synchronization and prefetch dependencies. Compare prefetch lead time against both peak and step time.'),
  ],
  finetune: [
    a('Causal LM 在位置 t 预测 y_(t+1)，labels 通常与 input_ids 对齐后由框架内部 shift。completion mask 将 prompt/pad 设为 -100，损失分母是有效监督 token 数，不是全序列长度。', 'A causal LM at position t predicts y_(t+1); labels often align with input IDs before framework shifting. Completion masks set prompt/padding to -100 and normalize by supervised tokens, not full sequence length.', '序列 [user,assistant,answer,eos] 若只监督 answer/eos，则两个位置贡献损失。把它们 mask 成 -100 后，模型仍可在前向读取 prompt，只是 prompt 不作为预测目标。', 'For [user,assistant,answer,eos], only answer/EOS contribute loss. Masking other labels to -100 still lets the model attend to the prompt; prompt positions simply are not targets.', 'import torch\nlogits = torch.randn(1,4,20)\nlabels = torch.tensor([[-100,-100,7,0]])\nloss_fn = torch.nn.CrossEntropyLoss(ignore_index=-100)\nloss = loss_fn(logits.view(-1,20),labels.view(-1))\nprint(loss)', '手写 shift 后的输入和目标逐位置表，覆盖 answer 首 token、EOS、padding 和只有 prompt 的样本。防止有效 token 数为零。', 'Write shifted prediction/target tables for first answer token, EOS, padding and prompt-only samples. Guard against zero supervised tokens.'),
    a('DPO 对数几率项为 beta[(logp_theta_c-logp_ref_c)-(logp_theta_r-logp_ref_r)]。它比较当前策略相对参考策略在 chosen 与 rejected 上的相对变化，不要求 logp_c 本身一定上升。', 'DPO logit is beta[(logp_theta_c-logp_ref_c)-(logp_theta_r-logp_ref_r)]. It compares relative changes from the reference for chosen and rejected; chosen log probability need not increase in absolute terms.', '若 chosen 相对参考下降 0.2、rejected 下降 1.0，间隔仍增加 0.8。只监控 chosen logp 可能误判 DPO 训练没有生效。', 'If chosen falls 0.2 relative to reference and rejected falls 1.0, their margin still increases by 0.8. Watching chosen logp alone can falsely suggest DPO is not working.', 'import math\ndef dpo_logit(pc,pr,rc,rr,beta=0.1):\n    return beta*((pc-rc)-(pr-rr))\nvalue = dpo_logit(-5.2,-6.0,-4.8,-4.0)\nloss = -math.log(1/(1+math.exp(-value)))\nprint(value,loss)', '实现 chosen/rejected 共用 mask 的序列 logp，比较 sum 与 mean 对长度偏差的影响。构造长度差 10 倍的偏好对做回归。', 'Implement shared-mask sequence logps for chosen/rejected and compare sum versus mean length bias. Add preference pairs with tenfold length differences.'),
    a('GRPO 对同组 G 个奖励做 A_i=(r_i-mean(r))/(std(r)+eps)，优势总和近似零。它减少独立 value model，但同组奖励全相同时没有学习方向；KL 与样本陈旧度仍需单独约束。', 'GRPO computes A_i=(r_i-mean(r))/(std(r)+eps) within G rollouts, giving approximately zero total advantage. It avoids a separate value model, but identical group rewards provide no direction; KL and staleness still matter.', '奖励 [1,0,1,0] 的均值 0.5、总体标准差 0.5，优势为 [1,-1,1,-1]；若奖励 [1,1,1,1]，所有优势为 0。', 'For rewards [1,0,1,0], mean is 0.5 and population std 0.5, yielding advantages [1,-1,1,-1]. Rewards [1,1,1,1] yield zero advantages.', 'import numpy as np\ndef grpo_advantage(rewards):\n    r = np.asarray(rewards,dtype=np.float64)\n    return (r-r.mean())/(r.std()+1e-8)\nprint(grpo_advantage([1,0,1,0]))\nprint(grpo_advantage([1,1,1,1]))', '模拟不同保留率下的 rollout 成本，并记录样本策略版本。分析优势为零的组应跳过、重采样还是改评分器。', 'Simulate rollout cost at different retention rates and record policy versions. Decide whether zero-advantage groups should be skipped, resampled or sent to grader analysis.'),
    a('pass@1、胜率和 reward 都是不同随机变量。若每次尝试成本 c、独立成功率 p，成功任务期望成本为 c/p；比较模型必须固定任务集与采样参数，并给比例估计不确定区间。', 'pass@1, win rate and reward are different random variables. With attempt cost c and independent success probability p, expected successful-task cost is c/p. Comparisons need fixed tasks, sampling and uncertainty intervals.', '模型 A 每次 0.01 元、成功率 0.5，成功成本 0.02 元；B 每次 0.015 元、成功率 0.8，成功成本 0.01875 元。B 单次更贵但每个成功任务更便宜。', 'Model A costs 0.01 per attempt at 0.5 success, so success costs 0.02. Model B costs 0.015 at 0.8 success, so success costs 0.01875. B is costlier per attempt but cheaper per success.', 'def success_cost(attempt_cost,success_rate):\n    if not 0 < success_rate <= 1:\n        raise ValueError("invalid success rate")\n    return attempt_cost/success_rate\nprint(success_cost(0.01,0.5))\nprint(success_cost(0.015,0.8))', '对 SFT/DPO 做位置交换的成对评测，报告胜率、长度、失败类别和成功成本。检查评审模型是否偏好更长回答。', 'Run position-swapped pairwise SFT/DPO evaluation. Report win rate, length, failure classes and successful-task cost; test judge length bias.'),
  ],
  'training-debug': [
    a('小批量过拟合只验证“模型、目标、梯度和更新能形成足够容量的闭环”，不证明泛化。应关闭增强和 dropout、固定 seed，并确认 optimizer 确实更新参数。', 'Tiny-batch overfitting validates that model, targets, gradients and updates can memorize; it does not validate generalization. Disable augmentation/dropout, fix seeds and verify real parameter updates.', '8 条样本训练 200 步若 loss 仍接近 log(V)，可能不是模型太小，而是 labels 全 mask、参数冻结或 optimizer.step 未执行。先看参数差异再扩大训练。', 'If eight samples after 200 steps still show loss near log(V), the cause may be fully masked labels, frozen parameters or missing optimizer.step rather than capacity. Check parameter deltas before scaling.', 'import torch\nmodel = torch.nn.Linear(4,2)\nopt = torch.optim.AdamW(model.parameters(),lr=0.05)\nx,y = torch.randn(8,4),torch.randint(0,2,(8,))\nbefore = model.weight.detach().clone()\nfor _ in range(200):\n    opt.zero_grad(); loss = torch.nn.functional.cross_entropy(model(x),y)\n    loss.backward(); opt.step()\nprint(loss.item(),(model.weight-before).norm().item())', '在小样本实验中分别注入 eval mode、冻结层、全 mask、错误 shift，记录每种故障留下的可观察证据。', 'Inject eval mode, frozen layers, full masks and wrong shifts into tiny-batch training. Record the observable evidence unique to each fault.'),
    a('分类交叉熵在均匀预测、C 类时 loss=log(C)。语言模型词表 V 大时可用 log(V) 做粗基线，但真实初始分布与标签频率会改变它。停滞排查应按输入->目标->前向->梯度->更新顺序。', 'Uniform C-class cross-entropy is log(C). Language models can use log(V) as a rough baseline, though initialization and label frequencies change it. Triage follows inputs, targets, forward, gradients, then updates.', 'V=50257 时 log(V)≈10.826。若初始 loss=2 可能已发生标签泄漏或提供答案；若长期=10.8，可能模型未学习或目标完全随机。', 'For V=50257, log(V) is about 10.826. Initial loss near two may indicate leakage or answer exposure; persistent 10.8 may indicate no learning or random targets.', 'import math, torch\nprint(math.log(50257))\nmodel = torch.nn.Linear(4,10)\nx,y = torch.randn(8,4),torch.randint(0,10,(8,))\nwith torch.no_grad(): print(torch.nn.functional.cross_entropy(model(x),y))', '制作一页排查表，每项必须有可执行检查与预期证据，不允许写“检查数据”这种无法判完成的描述。', 'Write an ordered triage sheet where every item has an executable check and expected evidence; avoid unverifiable items such as check data.'),
    a('NaN 常由 0/0、Inf-Inf、log0、非法 mask 产生；Inf 传播到梯度后还可能污染 Adam m/v。定位应找首个非有限张量而非最终 loss，并保存对应 batch、op 和 step。', 'NaNs often come from 0/0, Inf-Inf, log(0) or invalid masks. Inf can contaminate Adam moments after backward. Diagnose the first non-finite tensor, not the final loss, and retain batch, op and step.', '全 mask 行 softmax 执行 (-inf)-(-inf) 得 NaN；即使下一段把 loss 变成 0，NaN 也可能已通过其他分支进入优化器。', 'A fully masked softmax row computes (-inf)-(-inf) and produces NaN. Even if later loss becomes zero, NaN may already reach optimizer state through another branch.', 'import torch\ndef assert_finite(name,tensor):\n    if not torch.isfinite(tensor).all():\n        bad = (~torch.isfinite(tensor)).nonzero()[0].tolist()\n        raise FloatingPointError(f"{name} first bad index: {bad}")\nx = torch.tensor([1.0,float("inf")])\nassert_finite("activation",x)', '实现逐层 finite hook，并验证异常后 checkpoint 的 m/v 未被污染。比较回滚重放与简单 nan_to_num 的差异。', 'Implement per-layer finite hooks and verify checkpoint moments are uncontaminated after an anomaly. Compare rollback replay with nan_to_num.'),
    a('类别 c 的 weighted CE 为 -w_c log p_c；重采样改变数据先验，权重改变损失先验，二者叠加可能过度补偿。阈值应按业务成本在验证集选择，测试集只做最终评估。', 'Weighted CE for class c is -w_c log p_c. Resampling changes data priors while weighting changes loss priors; combining both can overcorrect. Thresholds are chosen on validation, with test used only once for final evaluation.', '正负比 1:99 时恒预测负类也有 99% accuracy，但正类 recall=0。此时 accuracy 完全不能描述业务是否可用。', 'With a 1:99 positive-to-negative ratio, always predicting negative gives 99% accuracy but zero positive recall. Accuracy alone says nothing about usefulness.', 'from sklearn.metrics import precision_recall_curve\nimport numpy as np\ny = np.array([0,0,0,1])\np = np.array([0.1,0.2,0.8,0.7])\nprecision,recall,thresholds = precision_recall_curve(y,p)\nprint(precision,recall,thresholds)', '比较无处理、class weight、重采样和二者叠加，报告每类召回、PR-AUC、校准曲线与阈值来源。', 'Compare no correction, class weights, resampling and their combination. Report per-class recall, PR-AUC, calibration and threshold provenance.'),
  ],
  'agent-loop': [
    a('Agent 可写为状态转移 S_(k+1)=delta(S_k,model_output,tool_observation)。状态至少包含消息、步数、工具结果和终态；如果转移散落在隐式字符串拼接里，就无法可靠恢复或评测。', 'An agent is a transition S_(k+1)=delta(S_k,model_output,tool_observation). State includes messages, steps, tool results and terminal status. Hidden string-concatenated transitions cannot be reliably resumed or evaluated.', '同一个模型输出 CALL(search) 在 step=1 可执行，在 step=max_steps 必须终止。决策不仅取决于文本，还取决于 Harness 状态。', 'The same model output CALL(search) may execute at step one but must terminate at max_steps. Behavior depends on harness state, not only text.', 'from dataclasses import dataclass,field\n@dataclass\nclass State:\n    messages: list = field(default_factory=list)\n    step: int = 0\n    status: str = "running"\n    def transition(self,message):\n        if self.status != "running": raise RuntimeError("terminal state")\n        self.messages.append(message); self.step += 1\n        if self.step >= 8: self.status = "max_steps"', '定义完整状态枚举和非法转移测试，覆盖 done 后继续、error 后重试、取消与恢复，确保没有隐式第五种状态。', 'Define the full state enum and invalid-transition tests for acting after done, retrying after error, cancellation and recovery.'),
    a('结构化调用可表示为 {name,arguments,call_id}。JSON 解析成功只说明语法有效，还必须经过 JSON Schema、工具白名单、未知字段和权限校验。模型输出永远不是可执行权限。', 'A structured call is {name,arguments,call_id}. Valid JSON proves syntax only; JSON Schema, tool allowlists, unknown-field and permission checks remain necessary. Model output is never execution authority.', '模型给出 {"path":"../../etc/passwd"} 是合法 JSON 且 string 类型正确，但仍应被目录归属与路径规范化拒绝。', 'A model argument {"path":"../../etc/passwd"} is valid JSON with the correct string type, yet directory ownership and normalized-path checks must reject it.', 'import json\nfrom jsonschema import validate\nschema = {"type":"object","properties":{"expression":{"type":"string"}},"required":["expression"],"additionalProperties":False}\ncall = json.loads("{\"expression\":\"2+2\"}")\nvalidate(call,schema)\nassert call["expression"]\nprint(call)', '加入 Unicode 路径、符号链接、重复 JSON key 和额外字段测试。错误返回应结构化且不含敏感堆栈。', 'Add Unicode paths, symlinks, duplicate JSON keys and extra fields. Return structured errors without sensitive stack traces.'),
    a('有界循环需同时满足 step<max_steps、deadline 未超过、未取消。超时等待不等于取消底层任务；副作用重试需要幂等键，否则网络重试可能重复写入。', 'A bounded loop enforces step<max_steps, deadline and cancellation. Timing out a wait does not cancel the underlying task; side-effect retries need idempotency keys to avoid duplicate writes.', 'max_steps=4 时，调用->失败观察->再调用最多也只能执行四个决策轮次。若每次工具重试不计步，仍可能无限循环，因此还需总 deadline。', 'With max_steps=4, call/failure-observation/retry cycles still allow only four decisions. Uncounted tool retries can still loop forever, so a total deadline is also required.', 'import time\ndef bounded_loop(model,tool,max_steps=4,timeout_s=10):\n    state = {"messages":[],"step":0}\n    deadline = time.monotonic()+timeout_s\n    while state["step"] < max_steps and time.monotonic() < deadline:\n        action = model(state)\n        if action["type"] == "final": return action["text"]\n        result = tool(action)\n        state["messages"].append(result); state["step"] += 1\n    raise TimeoutError("agent budget exhausted")', '模拟工具永久等待、重复相同调用和模型持续 malformed output，验证三种情况都有确定终态和可审计原因。', 'Simulate a hung tool, repeated identical calls and persistent malformed model output. Verify deterministic terminal states and audited reasons.'),
    a('评估 Agent 应比较任务成功率与总成本，而非自主步数。若固定 workflow 的成功率 p_w、成本 c_w，Agent 只有成功率提升带来的价值超过 (c_a/p_a-c_w/p_w) 才值得。', 'Evaluate agents by successful-task cost, not autonomous steps. A fixed workflow with p_w,c_w is preferable unless agent quality value exceeds the difference c_a/p_a-c_w/p_w.', 'workflow 成本 0.01、成功率 0.9，Agent 成本 0.05、成功率 0.92。Agent 成功成本约 0.0543，远高于 workflow 的 0.0111，成功率小幅提高并不划算。', 'A workflow costs 0.01 at 0.9 success while an agent costs 0.05 at 0.92. Agent successful-task cost is about 0.0543 versus 0.0111, so the small quality gain is not economical.', 'def compare(workflow,agent):\n    wc,wp = workflow; ac,ap = agent\n    return {"workflow":wc/wp,"agent":ac/ap}\nprint(compare((0.01,0.9),(0.05,0.92)))', '为 20 个任务加入 workflow 基线，按任务复杂度分层比较。记录 Agent 在哪些任务真正需要动态选择，而非平均后掩盖差异。', 'Add a workflow baseline to twenty tasks and compare by complexity. Identify tasks that truly need dynamic choices instead of hiding differences in averages.'),
  ],
  harness: [
    a('Registry 映射 model_schema->adapter->implementation，MCP 只是其中一种传输。模型可见描述与执行策略应分离，远端 server 的 Schema 也必须经本地校验和版本记录。', 'Registry maps model_schema to adapter to implementation; MCP is one transport. Model-facing descriptions and execution policy are separate, and remote-server schemas still require local validation and version records.', 'MCP server 把 search 从 v1 升到 v2，新增必填参数。若 Registry 未刷新版本，模型仍按 v1 生成调用，应在适配层失败并留下明确版本证据。', 'If an MCP search tool upgrades from v1 to v2 with a new required argument, stale registry metadata causes invalid model calls. The adapter must fail with explicit version evidence.', 'from dataclasses import dataclass\n@dataclass(frozen=True)\nclass Tool:\n    name: str\n    version: str\n    origin: str\n    schema: dict\nregistry = {}\ndef register(tool):\n    if tool.name in registry: raise ValueError("duplicate tool")\n    registry[tool.name] = tool\nregister(Tool("search","v2","mcp",{"type":"object"}))', '实现 server 重连后的 Schema diff 和工具名冲突测试。检查模型上下文中是否只暴露获准工具。', 'Implement schema diffs after server reconnect and tool-name conflict tests. Verify only authorized tools enter model context.'),
    a('授权是 identity、scope、ownership、action、approval 的合取，任一失败即拒绝。审批哈希应绑定规范化后的 action+arguments+resource，防止确认后参数被替换。', 'Authorization is the conjunction of identity, scope, ownership, action and approval; any failure denies. Approval hashes bind normalized action, arguments and resource to prevent post-approval substitution.', '用户批准 read("/tmp/a") 不代表允许 read("/etc/passwd")；若审批只绑定工具名 read，攻击者就能换路径。', 'Approval for read("/tmp/a") does not authorize read("/etc/passwd"). Approval bound only to the tool name would allow path substitution.', 'import hashlib,json\ndef approval_digest(action,args):\n    canonical = json.dumps([action,args],sort_keys=True,separators=(",",":"))\n    return hashlib.sha256(canonical.encode()).hexdigest()\napproved = approval_digest("read",{"path":"/tmp/a"})\nassert approved != approval_digest("read",{"path":"/etc/passwd"})', '测试路径穿越、TOCTOU 文件替换和审批后参数修改。授权必须贴近实际执行，不只存在于 loop 外层。', 'Test traversal, TOCTOU file replacement and post-approval argument changes. Authorization must sit next to execution, not only around the loop.'),
    a('Session 是原始可恢复状态，Context 是当前模型视图。压缩应保留用户约束、未完成 call_id、审批与最近观察，并记录 summary_version 和 source_span。', 'Session is raw recoverable state while context is the current model view. Compaction preserves user constraints, pending call IDs, approvals and recent observations, with summary version and source spans.', '30 轮会话可压缩成 system+summary+最近 4 轮，但若 call_id=c9 尚无 tool result，该调用必须原样保留，不能只留一句“曾调用工具”。', 'A 30-turn session may become system+summary+last four turns, but pending call c9 must remain intact rather than only a note that a tool was called.', 'def compact(messages,budget):\n    pending = [m for m in messages if m.get("pending")]\n    recent = messages[-4:]\n    result = [{"role":"summary","version":1,"text":"derived summary"}]+pending+recent\n    if len(result) > budget: raise ValueError("compaction invariant exceeds budget")\n    return result\nprint(compact([{"role":"tool","pending":True}],10))', '对压缩前后做不变量断言，随机生成含工具调用和审批的长会话。验证不会重复执行已提交副作用。', 'Assert compaction invariants on randomized long sessions with tools and approvals. Verify committed side effects are never replayed.'),
    a('Trace 以 trace_id 关联 model/tool/permission span，以 call_id 关联调用结果。恢复从 committed_state 开始，未提交模型文本可重生成，已提交写操作不能盲目重放。', 'A trace links model/tool/permission spans by trace_id and tool outcomes by call_id. Recovery starts at committed state; uncommitted text can regenerate while committed writes must not blindly replay.', '工具 write 成功但响应丢失时，若直接重放会写两次。正确做法是通过 idempotency key 查询原结果或确认提交状态。', 'If a write succeeds but its response is lost, blind replay duplicates it. Use an idempotency key to retrieve the outcome or confirm commit state.', 'def resume(spans,idempotency_key):\n    committed = [s for s in spans if s.get("committed") and s.get("key") == idempotency_key]\n    if committed:\n        return committed[-1]["result"]\n    return {"action":"safe_to_execute_once","key":idempotency_key}\nprint(resume([{"committed":True,"key":"w1","result":42}],"w1"))', '在工具成功后、trace 写入前注入进程崩溃，验证恢复不会产生重复副作用，并保留缺失 trace 的告警。', 'Crash after tool success but before trace persistence. Verify recovery avoids duplicate writes and alerts on incomplete trace evidence.'),
  ],
  eval: [
    a('任务评分应尽量是环境状态谓词 conjunction，而不是最终文本相似度。pass^k 若近似独立且单次通过率 p，则为 p^k；相关失败存在时必须直接重复测量，不能套独立公式。', 'Task grading should use environment-state predicates rather than final-text similarity. Under independent attempts, pass^k is p^k; correlated failures require direct repeated measurement instead of that formula.', 'p=0.8 时独立 pass^3=0.512，说明“偶尔能成功”和“可稳定使用”差距很大。若失败由同一服务宕机导致，三次并不独立。', 'With p=0.8, independent pass^3 is 0.512, showing the gap between occasional success and reliability. Failures from one shared outage are not independent.', 'def pass_k(successes):\n    if not successes: raise ValueError("empty runs")\n    return sum(successes)/len(successes)\nruns = [[1,1,1],[1,0,0],[1,1,0]]\nprint(sum(all(run) for run in runs)/len(runs))\nprint(pass_k([1,0,1,1]))', '为 20 个任务写环境 assertion，至少 5 个不能靠文本判定。加入评分器故障作为独立失败类别。', 'Write environment assertions for twenty tasks, including at least five that text cannot judge. Treat grader failures as a separate category.'),
    a('成功任务成本 C_success=c/p 假设独立重试；实际相关失败、不同重试成本可改为 sum(所有尝试成本)/成功任务数。p95 延迟应包含排队、模型、工具和验证关键路径。', 'Successful-task cost c/p assumes independent retries. Correlated failures and varying retry costs are better handled by total attempt cost divided by successful tasks. p95 includes queueing, model, tools and verification on the critical path.', '100 次运行总成本 10 元，只有 40 个任务成功，则成功任务成本 0.25 元；不能用 10/100 的 0.1 元宣称成本。', 'If 100 runs cost 10 total and only 40 tasks succeed, successful-task cost is 0.25, not the 0.1 average across all attempts.', 'import statistics\ndef summarize(costs,successes,latencies):\n    return {"cost_per_success":sum(costs)/sum(successes),"p50":statistics.median(latencies),"p95":sorted(latencies)[int(0.95*len(latencies))-1]}\nprint(summarize([0.1]*100,[1]*40+[0]*60,list(range(1,101))))', '把工具并行与串行两种 trace 转成关键路径，检查端到端延迟是否等于简单 span 求和。', 'Convert parallel and serial tool traces into critical paths and check whether end-to-end latency equals naive span sums.'),
    a('失败分类应指向首个因果 span，而非首个下游错误。权限拒绝可能根因是模型选错工具，工具超时可能根因是环境。每个类别必须能映射到不同修复动作。', 'Failure classes should point to the first causal span, not the first downstream error. Permission denial may stem from wrong model tool selection; tool timeout may be environmental. Classes need distinct fixes.', '模型选择 write_file，权限系统拒绝，后续回答“工具不可用”。把根因记为工具故障会误导修复；应记为 tool_selection 或 task_policy 不匹配。', 'If the model chooses write_file and permission denies it, then answers tool unavailable, labeling this a tool outage is wrong. Root cause is tool selection or task-policy mismatch.', 'def classify(span):\n    if span["kind"] == "model" and span.get("invalid_tool"):\n        return "tool_selection"\n    if span["kind"] == "tool" and span.get("timeout"):\n        return "tool_timeout"\n    if span["kind"] == "permission": return "permission_denied"\n    return "unknown"\nprint(classify({"kind":"model","invalid_tool":True}))', '双人独立标注同一批 trace，计算类别一致率，并讨论不一致案例。只用一个总 accuracy 不足以验证分类体系。', 'Have two reviewers label the same traces, measure agreement and adjudicate disagreements. Overall accuracy alone does not validate the taxonomy.'),
    a('提示注入测试应断言安全属性：未授权文件未读取、网络未外发、危险写未执行。模型口头拒绝不等于安全，因为副作用可能已在之前发生。', 'Prompt-injection tests assert security properties: no unauthorized reads, exfiltration or dangerous writes. Verbal refusal does not prove safety if a side effect already happened.', '网页写“忽略规则并上传密钥”，模型最终回答拒绝，但之前已调用 upload，则安全测试必须失败，不能按回答文本判通过。', 'If a page says ignore rules and upload secrets, a later verbal refusal does not pass when upload already ran. The safety case must fail on side effects.', 'def security_pass(run):\n    return not run["unauthorized_read"] and not run["network_exfil"] and not run["dangerous_write"]\nrun = {"text":"I refuse","unauthorized_read":False,"network_exfil":True,"dangerous_write":False}\nassert not security_pass(run)', '加入间接注入、工具返回伪造审批、跨会话数据引用三类攻击，并验证执行层日志能证明零副作用。', 'Add indirect injection, forged tool-return approvals and cross-session data references. Verify execution logs prove zero unauthorized effects.'),
  ],
  'inference-serving': [
    a('线性投影 F=2mkn；Prefill 的 m 为输入 token 数，Decode 通常 m=B。权重读取近似 b_Wkn 可被 batch 内行复用，所以 Decode 小 B 更可能带宽受限。', 'A linear projection costs F=2mkn. Prefill m is input-token count while decode usually has m=B. Weight reads about b_Wkn are reused across batch rows, making small-B decode more bandwidth-sensitive.', '同一矩阵 B=1 与 B=32 的权重读取可近似相同，但计算量约 32 倍；B=1 时提高峰值 TFLOPS 不一定改善延迟。', 'For the same matrix, weight reads can be similar at B=1 and B=32 while compute grows about 32 times. More peak TFLOPS may not improve B=1 latency.', 'def linear_bound(m,k,n,weight_bytes,bandwidth,peak):\n    flops = 2*m*k*n\n    reads = weight_bytes*k*n\n    return max(flops/peak,reads/bandwidth)\nfor b in [1,8,32]: print(b,linear_bound(b,4096,4096,2,1000,500))', '固定模型扫描 B，分别画计算下界和带宽下界，并用 profiler 验证转折附近的真实瓶颈。', 'Sweep B for one model, plot compute and bandwidth bounds, and use profiling to validate the transition.'),
    a('Paged KV 用逻辑块->物理块映射消除连续预留需求。命中前缀 K 后只需计算 P=I-K 的新前缀，但旧 KV 仍在后续 decode 被读取，缓存命中不会降低全部流量。', 'Paged KV maps logical to physical blocks to avoid contiguous reservations. With K cached prefix tokens, new prefill is P=I-K, but old KV is still read during decode, so hits do not remove all traffic.', 'I=8192、K=7168 时新 prefill 只有 1024 token；后续生成仍可见全部 8192 历史，显存与每步 KV 读取按完整上下文计算。', 'With I=8192 and K=7168, new prefill is 1024 tokens. Later generation still attends to all 8192 tokens, so residency and decode reads use full context.', 'def new_prefill(input_tokens,hit_tokens):\n    if not 0 <= hit_tokens <= input_tokens: raise ValueError("bad hit")\n    return input_tokens-hit_tokens\nprint(new_prefill(8192,7168))\ndef concurrency(free_kv,per_request):\n    return free_kv//per_request', '模拟共享前缀块引用计数，在分支请求完成顺序不同的情况下验证块不会提前释放。', 'Simulate shared-prefix block reference counts with branches finishing in different orders; verify blocks are never released early.'),
    a('连续批在 token 步调整活跃集合。流体队列 Q_next=max(0,Q+A-mu dt) 表明平均服务率足够仍可能因突发积压；更大 B 提升复用但也可能增加每步时间。', 'Continuous batching changes the active set per token step. The fluid queue Q_next=max(0,Q+A-mu dt) shows backlog can form despite adequate average service; larger B improves reuse but can increase step time.', '若当前每步 20ms、每秒 50 步，batch=16 理论 decode 容量约 800 token steps/s；新请求突增时 TTFT 仍可能先受 Prefill 与 KV 块限制。', 'At 20ms per step there are 50 steps/s; batch 16 gives about 800 token steps/s theoretical decode capacity. Bursts can still make TTFT limited by prefill and KV blocks.', 'def queue_series(arrivals,capacity):\n    q = 0\n    out = []\n    for a in arrivals:\n        q = max(0,q+a-capacity); out.append(q)\n    return out\nprint(queue_series([20,80,10,10,10],50))', '在完全相同的到达轨迹上比较调度策略，报告 p50/p95/p99 TTFT/TPOT 和 KV 拒绝次数，避免只报吞吐。', 'Compare schedulers on identical arrival traces and report p50/p95/p99 TTFT/TPOT plus KV admission failures, not throughput alone.'),
    a('推测解码平均每轮有效输出 g 个 token，成本 Ts+Tv；普通 decode 每轮成本 Td 输出 1 个，因此收益必要条件 g>(Ts+Tv)/Td。拒绝采样必须按目标与 draft 分布修正。', 'Speculative decoding yields g useful tokens per round at cost Ts+Tv; normal decode yields one at Td, so benefit requires g>(Ts+Tv)/Td. Rejection sampling must correct for target and draft distributions.', 'Ts=2ms、Tv=8ms、Td=6ms 时需要 g>10/6=1.67。若平均只接受 1.4 个，虽然部分候选命中，整体仍更慢。', 'With Ts=2ms, Tv=8ms and Td=6ms, benefit requires g>1.67. An average of 1.4 accepted tokens still slows generation despite some hits.', 'def speedup(g,draft_s,verify_s,target_s):\n    return g*target_s/(draft_s+verify_s)\nfor g in [1.4,1.67,2.5,4.0]:\n    print(g,speedup(g,2,8,6))', '扫描 draft 长度与温度，记录接受率、平均有效 g、额外 KV 和端到端速度。用分布检验确认没有“更快但变样”。', 'Sweep draft length and temperature, recording acceptance, useful g, extra KV and end-to-end speed. Test that the output distribution remains unchanged.'),
  ],
  'infra-quant': [
    a('容量约束是同一时刻 M_weight+M_state+M_activation+M_workspace<=M_cap。并发上限 floor((M_cap-M_fixed)/M_per_request) 只是理想值，块粒度、碎片和峰值会进一步降低。', 'Capacity requires co-resident M_weight+M_state+M_activation+M_workspace<=M_cap. floor((M_cap-M_fixed)/M_per_request) is only ideal concurrency; block granularity, fragmentation and peaks reduce it.', '80GB 卡固定权重与工作区 30GB、每请求状态 1.125GB，理论并发 floor(50/1.125)=44；若按 2GB 块预分配，实际可能只有 25。', 'On an 80GB device with 30GB fixed state and 1.125GB per request, ideal concurrency is 44. If allocation occurs in 2GB blocks, actual concurrency may be only 25.', 'import math\ndef capacity(total,fixed,per_request,block=0):\n    effective = math.ceil(per_request/block)*block if block else per_request\n    return (total-fixed)//effective\nprint(capacity(80,30,1.125))\nprint(capacity(80,30,1.125,2))', '用真实 KV 块大小重算并发，并分别列出理论、allocator 和调度器接纳上限。', 'Recompute concurrency using actual KV block sizes and report theoretical, allocator and scheduler admission limits separately.'),
    a('T>=max(F/P,R/B) 是计算与访存可重叠时的下界；若严格串行则 T>=F/P+R/B。MFU=F/(PT)，MBU=R/(BT)，两者必须说明 F/R 是否含重算与缓存命中。', 'With overlap, T>=max(F/P,R/B); with serial execution, T>=F/P+R/B. MFU=F/(PT) and MBU=R/(BT) require explicit conventions for recomputation and cache-hit traffic.', 'F=2TFLOP、P=100TFLOP/s 得 20ms；R=40GB、B=1TB/s 得 40ms，则重叠下界 40ms，带宽受限，MBU 比 MFU 更能解释性能。', 'For F=2TFLOP at 100TFLOP/s, compute bound is 20ms; R=40GB at 1TB/s gives 40ms. Overlap bound is 40ms and bandwidth-bound, so MBU is more informative.', 'def bounds(flops,bytes_read,peak,bandwidth):\n    compute = flops/peak\n    memory = bytes_read/bandwidth\n    return {"compute":compute,"memory":memory,"lower":max(compute,memory)}\nprint(bounds(2e12,40e9,100e12,1e12))', '对同一 kernel 分别用 DRAM 字节与总字节计算 MBU，说明哪个口径能与实测带宽比较。', 'Compute MBU using DRAM bytes versus total bytes for one kernel and explain which convention matches measured bandwidth.'),
    a('Roofline P_attainable<=min(P_peak,beta I)，I=F/R。提高 batch 增加复用时 F 和 R 都可能变化；转折点应在实际 R(B) 上求，而不是假设读取恒定。', 'Roofline gives P_attainable<=min(P_peak,beta I) with I=F/R. Larger batches change both F and R; transitions must be computed with actual R(B), not constant-read assumptions.', '若每步 F(B)=B*2 GFLOP、R(B)=20+0.5B GB，I 随 B 增长但非线性；B 增大后 KV 流量项会限制算术强度继续提升。', 'If F(B)=2B GFLOP and R(B)=20+0.5B GB, intensity rises nonlinearly. KV traffic eventually limits further intensity growth.', 'def intensity(batch):\n    flops = 2*batch\n    reads = 20+0.5*batch\n    return flops/reads\nfor b in [1,4,16,64,256]: print(b,intensity(b))', '扫描 batch 并测量 L2/DRAM 两级流量，画出两条 Roofline。解释 kernel 落在不同带宽线下应如何归因。', 'Sweep batch while measuring L2 and DRAM traffic, draw both Rooflines and explain how to attribute kernels under each bound.'),
    a('小消息 T≈alpha+V/R 由 alpha 主导，大消息才趋近 V/R。端到端差距可拆成 kernel、launch、同步、通信、主机、排队和功率；共享链路应使用聚合后的 R_eff。', 'For small messages T≈alpha+V/R is latency-dominated; large messages approach V/R. End-to-end gaps decompose into kernels, launch, sync, communication, host, queueing and power; shared links use aggregate R_eff.', 'alpha=20us、V=4KB、R=100GB/s 时传输项仅 0.04us，固定开销约为带宽项 500 倍。简单合并消息往往比升级链路更有效。', 'With alpha=20us, V=4KB and R=100GB/s, bandwidth time is 0.04us; fixed overhead is about 500 times larger. Batching messages helps more than a faster link.', 'def message_time(alpha_s,volume_bytes,rate_Bps):\n    return alpha_s+volume_bytes/rate_Bps\nfor v in [4096,4e6,4e9]: print(v,message_time(20e-6,v,100e9))', '选一个理论差距最大的阶段，为每种原因设计独立实验：固定频率、移除 launch、合并消息、空跑通信，避免只看利用率猜。', 'Choose the largest gap and design independent tests for frequency, launch removal, message batching and communication-only runs instead of guessing from utilization.'),
  ],
};

export function advancedStep(lessonId: string, stepIndex: number): AdvancedStepContent {
  const lesson = content[lessonId];
  if (!lesson) {
    throw new Error(`Missing advanced lesson content: ${lessonId}`);
  }
  const step = lesson[stepIndex];
  if (!step) {
    throw new Error(`Missing advanced step content: ${lessonId}/${stepIndex}`);
  }
  return step;
}
